SELECT COUNT(*) AS negocios_500m
FROM negocios
WHERE ST_Distance(
  ST_Transform(geom, 'EPSG:4326', 'EPSG:6372', always_xy := true),
  ST_Transform(ST_SetSRID(ST_MakePoint(-103.3870, 20.6950), 4326), 'EPSG:4326', 'EPSG:6372', always_xy := true)
) <= 500;

